string public baseURI;
address public proxyRegistryAddress;

uint256 public constant MAX_SUPPLY = 1;
uint256 public minBidStep = 0.25 ether;

uint256 public constant buyNowPrice = 15 ether;
uint256 public constant buyNowPriceUntilBid = 14.75 ether;
uint256 public buyNowMultiplier = 20;
bool public boughtNow;

uint256 public auctionDuration = 24 hours;
bool public auctionStarted;
uint256 public auctionStartTimestamp;
bool public auctionEnded;
uint256 public auctionEndTimestamp;

uint256 public highestBid = 0.9 ether;
