require(block.timestamp < auctionEndTimestamp, "Auction has been finished");

uint256 newBid = bids[_msgSender()] + msg.value;
require(newBid >= highestBid + minBidStep, "Bid must be at least 0.25 ETH higher than the highest bid");

bids[_msgSender()] += msg.value;
highestBid = newBid;
highestBidder = _msgSender();

if (!hasAddressBidded[_msgSender()]){
hasAddressBidded[_msgSender()] = true;
totalBidAddresses++;
bidAdresses.push(_msgSender());
